package blockbranch.mixin.qa;
import blockbranch.realistic.*;import com.llamalad7.mixinextras.injector.wrapmethod.WrapMethod;import com.llamalad7.mixinextras.injector.wrapoperation.*;import net.minecraft.world.level.*;import net.minecraft.world.level.chunk.*;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.feature.Feature;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.util.RandomSource;import java.util.*;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.At;
@Mixin(value=OverworldStructures.class,remap=false)
abstract class CryptCoverageWorkMixin {
 @WrapMethod(method="fit")private static Optional<Structure.GenerationStub> fit(Structure structure,Structure.GenerationContext c,java.util.function.Function<Structure.GenerationContext,Optional<Structure.GenerationStub>> nativeGeneration,Operation<Optional<Structure.GenerationStub>> original){if(!AdmissionWorkTrace.ON)return original.call(structure,c,nativeGeneration);String id=String.valueOf(c.registryAccess().lookupOrThrow(Registries.STRUCTURE).getKey(structure));var span=AdmissionWorkTrace.begin("fit."+id,c.chunkPos().x(),c.chunkPos().z());boolean accepted=false;try{var result=original.call(structure,c,nativeGeneration);accepted=result.isPresent();return result;}finally{AdmissionWorkTrace.end(span,accepted);}}
 @WrapOperation(method={"geode","smallStructures"},at=@At(value="INVOKE",target="Lnet/minecraft/world/level/levelgen/feature/Feature;place(Lnet/minecraft/world/level/WorldGenLevel;Lnet/minecraft/world/level/chunk/ChunkGenerator;Lnet/minecraft/util/RandomSource;Lnet/minecraft/core/BlockPos;)Z"))private static boolean feature(Feature feature,WorldGenLevel level,ChunkGenerator generator,RandomSource random,BlockPos pos,Operation<Boolean> original){if(!AdmissionWorkTrace.ON)return original.call(feature,level,generator,random,pos);String id=String.valueOf(level.registryAccess().lookupOrThrow(Registries.FEATURE).getKey(feature));var span=AdmissionWorkTrace.begin("feature."+id,pos.getX()>>4,pos.getZ()>>4);boolean placed=false;try{placed=original.call(feature,level,generator,random,pos);return placed;}finally{AdmissionWorkTrace.end(span,placed);}}
}
